NAME = 'NlCanisius1939: Petrus Canisius Translation'
BOOK = 'I Peter'

CHAPTERS = {
    1: {
        1: 'Petrus, apostel van Jesus Christus, aan de pelgrims der Verstrooiing van Pontus, Galátië, Kappadócië, Azië en Bitúnië, die zijn uitverkoren,',
        2: 'naar de voorwetenschap van God den Vader en door de heiliging van den Geest, tot de gehoorzaamheid aan Jesus Christus en de besprenkeling met zijn Bloed: Genade en vrede zij u in volle mate.',
        3: 'Geloofd zij de God en Vader van onzen Heer Jesus Christus, die in zijn grote barmhartigheid door de opstanding van Jesus Christus uit de doden ons deed wedergeboren worden tot een levende hoop,',
        4: 'tot een onbederflijke, onbezoedelde en onvergankelijke erfenis. Deze is in de hemel weggelegd voor u,',
        5: 'die in Gods kracht door het geloof wordt behouden, om tot een zaligheid te geraken, welke gereed ligt voor haar openbaring op het einde der tijden.',
        6: 'Dan zult gij u verheugen, al wordt gij ook thans, indien het zo wezen moet, voor korte tijd door allerlei beproevingen gekweld.',
        7: 'Want wanneer uw geloof de proef heeft doorstaan, dan heeft het hoger waarde dan vergankelijk goud, dat door het vuur is gelouterd; en zal het strekken tot lof en eer en roem bij de verschijning van Jesus Christus.',
        8: 'Hem hebt gij lief, ofschoon gij Hem niet hebt gezien; in Hem gelooft gij, ofschoon gij Hem thans nog niet ziet; verheugt u dus met onuitsprekelijke en verheerlijkte vreugde,',
        9: 'omdat gij het doel van uw geloof bereikt, de zaligheid uwer zielen.',
        10: 'Naar deze zaligheid hebben de profeten gezocht en gevorst; zij profeteerden over de genade, die voor u was bestemd;',
        11: 'ze onderzochten, op wat tijd en wat uur de Geest van Christus gedoeld heeft, die in hen was en het lijden voorzegde, dat Christus zou treffen, en de heerlijkheid, die daarop volgen zou.',
        12: 'Maar het werd hun geopenbaard, dat ze met dit alles zichzelf niet dienden, maar u. En thans is u dit alles verkondigd door hen, die u de blijde boodschap brachten door den heiligen Geest, die uit de hemel is neergezonden; en engelen zelfs zijn begerig, er een blik in te slaan.',
        13: 'Omgordt dus de lenden van uw verstand en weest bezonnen; richt heel uw hoop op de genade, die u geschonken wordt, als Jesus Christus verschijnt.',
        14: 'Voegt u, als gehoorzame kinderen, niet naar uw vroegere lusten uit de tijd der onwetendheid;',
        15: 'maar weest heilig in heel uw wandel, zoals Hij heilig is, die u riep.',
        16: 'Want er staat geschreven: "Weest heilig, omdat Ik heilig ben."',
        17: 'En wanneer gij Hem aanroept als Vader, die zonder aanzien des persoons een ieder oordeelt naar zijn werken, brengt dan in vreze de tijd van uw ballingschap door.',
        18: 'Want gij weet, dat gij niet met vergankelijk zilver of goud zijt vrijgekocht uit uw ijdele levenswandel, die van uw vaders stamt,',
        19: 'maar door het kostbaar Bloed van Christus, als van een Lam zonder vlek of gebrek.',
        20: 'Vóór de grondvesting der wereld was Hij daartoe voorbestemd, maar eerst op het einde der tijden is Hij verschenen terwille van u.',
        21: 'Door Hem gelooft gij in God, die Hem van de doden heeft opgewekt en verheerlijkt; en zó is uw geloof ook hoop op God.',
        22: 'En nu gij door gehoorzaamheid aan de waarheid uw zielen tot ongeveinsde broederliefde hebt geheiligd, nu moet gij elkander van harte en vurig beminnen.',
        23: 'Want gij zijt wedergeboren niet uit vergankelijk, maar uit onvergankelijk zaad, door het levend en blijvend woord van God.',
        24: 'Want: "Alle vlees is als gras, Heel zijn glorie als een bloem in het gras. Het gras verdort, de bloem valt af;',
        25: 'Maar het woord des Heren houdt in eeuwigheid stand!" En dit is het woord, dat onder u is verkondigd.',
    },
    2: {
        1: 'Legt dan af alle boosheid, valsheid, huichelarij, afgunst en alle kwaadsprekerij.',
        2: 'Weest, als pasgeboren kinderkens, begerig naar onvervalste geestelijke melk, om daardoor op te groeien tot zaligheid,',
        3: 'zo "gij reeds gesmaakt hebt, dat de Heer goedertieren is."',
        4: 'Nadert tot Hem, de levende steen, —door de mensen verworpen, maar uitverkoren en kostbaar bij God,',
        5: 'en laat u als levende stenen opbouwen tot een geestelijke tempel, bestemd voor een heilig priesterschap, dat geestelijke offers brengt, welgevallig aan God door Jesus Christus.',
        6: 'Daarom staat er in de Schrift: "Zie, Ik leg in Sion een uitverkoren steen, een kostbare hoeksteen; En wie in Hem gelooft, wordt niet beschaamd."',
        7: 'Voor u dus de eer, omdat gij gelooft. Maar voor wie niet geloven, blijft het gelden: "De steen, die de bouwlieden hadden verworpen, Is hoeksteen geworden;',
        8: 'Maar ook een steen des aanstoots, En een rotsblok, waarover men struikelt." Omdat ze het woord niet geloven, stoten ze zich; en hiertoe zijn ze voorbestemd.',
        9: 'Gij echter zijt een uitverkoren geslacht, een koninklijk priesterdom, een heilige natie, een aangeworven volk: om te verkondigen de deugden van Hem, die u riep uit de duisternis tot zijn wonderbaar licht.',
        10: 'Gij, vroeger geen volk, nu Gods volk; vroeger van genade verstoken, nu begenadigd.',
        11: 'Geliefden, ik vermaan u, als pelgrims en vreemdelingen, u verre te houden van de vleselijke lusten, die strijd voeren tegen de ziel.',
        12: 'Leidt onder de heidenen een voorbeeldig leven, opdat zij uw wandel, waarover ze thans u als boosdoeners lasteren, uit uw goede werken zullen leren kennen op de dag der bezoeking, en dan glorie zullen brengen aan God.',
        13: 'Weest onderdanig aan ieder menselijk gezag om ‘s Heren wil: aan den koning als opperheer;',
        14: 'aan de landvoogden als zijn gezanten, om de boosdoeners te straffen en de goeden te prijzen.',
        15: 'Want het is de wil van God, dat gij, door het goede te doen, het onverstand van domme mensen tot zwijgen brengt.',
        16: 'Doet het als vrije mannen; niet als mensen, die de vrijheid als een dekmantel der boosheid gebruiken, maar als dienstknechten Gods.',
        17: 'Houdt alle mensen in ere, hebt de gemeenschap lief; vreest God, eert den koning!',
        18: 'Gij slaven, weest onderdanig aan uw meesters met alle ontzag; niet alleen aan de goede en vriendelijke, maar ook aan de lastige.',
        19: 'Want dit is een welgevallige daad, wanneer men uit gewetensplicht tegenover God het leed verdraagt, dat men onverdiend moet lijden.',
        20: 'Wat eer toch steekt er in, gelaten te zijn, als gij geslagen wordt, omdat gij misdaan hebt? Neen, dit is welgevallig aan God: gelaten te zijn, als gij lijdt, ofschoon gij goed hebt gehandeld.',
        21: 'Hiertoe immers zijt gij geroepen; want ook Christus heeft geleden voor u, en u een voorbeeld nagelaten, opdat gij zijn voetstappen zoudt volgen.',
        22: 'Hij heeft geen zonde bedreven, en er was geen bedrog in zijn mond;',
        23: 'toch hoonde Hij niet, als Hij gehoond werd, en dreigde Hij niet, als Hij leed; maar Hij liet het over aan Hem, die met rechtvaardigheid oordeelt.',
        24: 'Hij zelf heeft aan het kruishout in zijn Lichaam onze zonden gedragen, opdat wij, van de zonden ontlast, voor de gerechtigheid zouden leven. Door zijn striemen zijt gij genezen;',
        25: 'want als schapen hebt gij rondgedwaald, maar thans zijt gij teruggekeerd tot den Herder, tot Hem, die uw zielen behoedt.',
    },
    3: {
        1: 'Eveneens moet gij, vrouwen, onderdanig zijn aan uw mannen; opdat ook zij, die misschien nog onwillig staan tegenover het woord, zonder woord, worden gewonnen door het gedrag hunner vrouwen,',
        2: 'wanneer ze uw reine, ingetogen wandel bespeuren.',
        3: 'Uw tooi moet niet in uiterlijke dingen bestaan: in haarvlechten, gouden smuk en klederdracht,',
        4: 'maar in den verborgen mens van het hart: in de onvergankelijke tooi van een zachtmoedige en ingetogen geest, die kostbaar is in Gods oog.',
        5: 'Zo immers tooiden zich vroeger ook de heilige vrouwen, die haar hoop stelden op God; aan haar mannen waren ze onderdanig,',
        6: 'zoals Sara aan Abraham gehoorzaam was, en hem "heer" heeft genoemd. Haar kinderen zijt gij geworden door het goede te doen, en geen enkel schrikbeeld te vrezen.',
        7: 'Eveneens moet gij, mannen, op redelijke wijze met uw vrouwen verkeren als met het zwakkere vat, en haar in ere houden als medeerfgenamen van de genade des levens, opdat uw gebeden niet worden belemmerd.',
        8: 'Ten slotte, weest allen eensgezind, deelnemend voor elkander, vol broederliefde, barmhartig, bescheiden;',
        9: 'vergeldt geen kwaad met kwaad, of schelden met schelden, maar zegent elkander veeleer; gij zijt toch geroepen, om zegen te erven.',
        10: 'Immers: "Wie het leven wil liefhebben, En goede dagen wil zien: Beware zijn tong voor het kwaad, En zijn lippen voor leugen;',
        11: 'Hij vluchte het kwaad, doe enkel wat goed is, Zoeke de vrede en jage hem na.',
        12: 'Want de ogen des Heren zijn op de vromen gericht, Zijn oren naar hun smeken gekeerd; Maar ‘s Heren aanschijn blikt grimmig tegen de bozen."',
        13: 'En wie zal u kwaad doen, wanneer gij ijverig zijt in het goede?',
        14: 'Maar al zoudt gij ook lijden om de gerechtigheid, zalig zijt gij! "Vreest niet voor hen, en laat u niet ontrusten."',
        15: 'Heiligt Christus, den Heer, in uw harten; weest altijd tot verantwoording bereid aan iedereen, die u rekenschap vraagt van de hoop, die in u leeft.',
        16: 'Doet het echter met zachtheid en schroom en met een goed geweten, opdat zij, die op uw goede wandel in Christus smalen, over hun lastertaal beschaamd mogen staan.',
        17: 'Want het is beter te lijden, zo God het wil, wanneer men goed doet, dan wanneer men kwaad bedrijft.',
        18: 'Immers ook Christus is éénmaal voor de zonden gestorven, een Rechtvaardige voor ongerechten, —om u te brengen tot God. Maar ter dood gebracht naar het Vlees, is Hij ten leven gewekt naar den Geest.',
        19: 'In den Geest is Hij dan ook aan de geesten in de kerker gaat preken:',
        20: 'aan hen, die eertijds onwillig waren geweest, toen in de dagen van Noë Gods lankmoedigheid bleef wachten, totdat de ark was gebouwd. Hierin werden enigen—acht personen, —gered door het water heen.',
        21: 'Als voorafgebeeld Doopsel redt thans dit water ook u; niet als een afwassing van de onreinheid naar het vlees, maar als een bede tot God om een goed geweten, door de opstanding van Jesus Christus.',
        22: 'Hij is opgestegen ten hemel, en is gezeten aan de rechterhand Gods, terwijl engelen en machten en krachten aan Hem zijn onderworpen.',
    },
    4: {
        1: 'Daar Christus nu naar het vlees heeft geleden, moet ook gij u wapenen met dezelfde gedachte: wie lijdt naar het vlees, is los van de zonde;',
        2: 'zodat gij niet langer naar de lusten der mensen, maar naar de wil van God de tijd doorleeft, die u rest in het vlees.',
        3: 'Want lang genoeg heeft de tijd geduurd, die nu voorbij is, waarin gij de zin der heidenen deedt, en geleefd hebt in losbandigheid, wellust, dronkenschap, brasserij, drinkgelagen en zondige afgoderij.',
        4: 'En nu staan ze vreemd te zien en lasteren ze u, omdat gij niet meedraaft naar dezelfde modderpoel van ongebondenheid;',
        5: 'maar ze zullen hierover rekenschap hebben te geven aan Hem, die gereed staat, om levenden en doden te oordelen.',
        6: 'Immers juist hierom is ook aan de doden de blijde tijding gebracht, opdat ze bij God naar de geest zouden leven, al zijn ze ook bij de mensen geoordeeld naar het vlees.',
        7: 'Het einde nadert van alle dingen! Beheerst dus uzelf en weest bezonnen, opdat gij kunt bidden.',
        8: 'Draagt vóór alles elkander vurige liefde toe; want de liefde bedekt een menigte zonden.',
        9: 'Weest gastvrij jegens elkander, zonder te morren.',
        10: 'Dient elkander met de genadegaven, zoals elk ze ontving, als goede beheerders van de vele genaden van God:',
        11: 'wanneer iemand spreekt, het zij als Gods woord; wanneer iemand dient, het geschiede door de kracht, door God hem verleend. Moge dan in alles God worden verheerlijkt door Jesus Christus, wien de heerlijkheid is en de kracht in de eeuwen der eeuwen. Amen!',
        12: 'Geliefden, staat niet verbaasd over de brand der beproeving, die bij u uitslaat, alsof u iets vreemds overkwam!',
        13: 'Maar verheugt u veeleer, naarmate gij deel hebt aan het lijden van Christus, opdat gij ook blijde moogt juichen als zijn glorie verschijnt.',
        14: 'Zalig zijt gij, zo gij om Christus’ naam smaad ondergaat; want dan rust op u de Geest der glorie, de Geest van God.',
        15: 'Immers niemand van u mag lijden als moordenaar of dief, als misdadiger of oproermaker;',
        16: 'maar lijdt hij als christen, hij schame zich niet, doch verheerlijke God om die naam.',
        17: 'Want de tijd van het oordeel is daar, dat begint met Gods huis. Maar wanneer het met ons gaat beginnen, wat zal dan het einde zijn van hen, die niet gehoorzamen aan het Evangelie van God?',
        18: 'En wanneer de rechtvaardige ternauwernood wordt gered, waar komt dan de goddeloze en zondaar terecht?',
        19: 'Daarom ook moeten zij, die naar Gods wil lijden verduren, hun zielen veilig stellen bij den getrouwen Schepper, door het goede te doen.',
    },
    5: {
        1: 'De priesters onder u vermaan ik dus: ik, die hun medepriester ben, de getuige ook van Christus’ lijden, en hun deelgenoot van de heerlijkheid, die geopenbaard zal worden:',
        2: 'Weidt Gods kudde, die aan uw zorgen is toevertrouwd; niet uit dwang, maar gewillig, zoals het God behaagt; niet uit winzucht, maar uit toegenegenheid;',
        3: 'niet als dwingelanden over de u toegewezen groepen, maar als voorbeeld der kudde.',
        4: 'Dan zult gij de onverwelkbare krans der glorie behalen, wanneer de opperste Herder verschijnt.',
        5: 'En gij jongeren, weest onderdanig aan de priesters! Gij allen, weest tegenover elkaar met het livrei der nederigheid bekleed; want "God weerstaat de hoogmoedigen, maar aan de nederigen geeft Hij genade."',
        6: 'Vernedert u dus onder Gods machtige hand, opdat Hij u te zijner tijd moge verheffen.',
        7: 'Werpt op Hem al uw bekommernis; want Hij draagt zorg voor u.',
        8: 'Weest bezonnen en waakzaam! De duivel, uw vijand, zwerft rond als een brullende leeuw, op zoek wien hij verslinden zal.',
        9: 'Weerstaat hem, sterk door het geloof! Denkt er aan, dat aan uw broeders, over de wereld verspreid, het lijden is toegemeten in dezelfde mate.',
        10: 'De God van alle genade, die u in Christus riep tot zijn eeuwige glorie, Hij zal u na kortstondig lijden oprichten en sterken, stevigen en bevestigen.',
        11: 'Hem is de kracht in de eeuwen der eeuwen. Amen!',
        12: 'Met behulp van Silvanus, dien ik hoogschat als een trouw broeder voor u, heb ik in het kort u geschreven, om u te bemoedigen, en u te verzekeren, dat dit inderdaad waarachtige genade van God is. Blijft daarin vaststaan!',
        13: 'De mede-uitverkorene in Babylon, en Markus mijn zoon, groeten u. Groet elkander met een liefdekus.',
        14: 'Vrede zij u allen, die in Christus zijt!',
    },
}
